mkdir -p /tmp/lamp-room6 && cd /tmp/lamp-room6 && RUN=/Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/plantation/crew/lamp-13 && sed -e 's#^  // layers(#  layers(#' -e 's#^  // bed(#  bed(#' $RUN/parts/room-6.mjs > room6-probe.mjs && cat > probe.mjs <<'EOF'
// Scratch probe: applies room 6's furniture (uncommented copy) plus candidate lamps to a COPY of build.nbt.
import { load, layers, bed } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { build } from "./room6-probe.mjs";
const [src, out, lampsJson] = process.argv.slice(2);
const g = load(src);
build(g);
for (const [x, y, z, block, state] of JSON.parse(lampsJson || "[]")) g.set(x, y, z, block, state);
g.save(out);
console.log("saved", out);
EOF
